// @ts-nocheck

const thetaMechVar   = env.get("theta_mechanical_variable_name");
const thetaTargetVar = env.get("theta_target_variable_name");
const thetaElVar     = env.get("theta_electrical_variable_name");

const name = msg.payload.variablename;
const data = msg.payload.variabledata;

if (!Array.isArray(data) || data.length === 0) {
    return [null, null, null];
}

const sample = data[data.length - 1];
const angle = Number(sample.y);

if (!Number.isFinite(angle)) {
    return [null, null, null];
}

const r = 20.0;

let displayName = name;

if (name === thetaMechVar) {
    displayName = "theta_mech";
} else if (name === thetaTargetVar) {
    displayName = "theta_target";
} else if (name === thetaElVar) {
    displayName = "theta_el";
}

const out = {
    topic: displayName,
    payload: {
        x: r * Math.cos(angle),
        y: r * Math.sin(angle)
    }
};

if (name === thetaMechVar) {
    return [out, null, null];
}

if (name === thetaTargetVar) {
    return [null, out, null];
}

if (name === thetaElVar) {
    return [null, null, out];
}

return [null, null, null];

// @ts-nocheck

const variableName = msg.topic;
const key = "stm32_" + variableName;

const variable = flow.get("$parent." + key);

if (!variable) {
    return null;
}

const value = Number(msg.payload);

if (!Number.isFinite(value)) {
    return null;
}

msg.topic = "write";

msg.payload = {
    variablelist: [
        {
            address: variable.address,
            type: variable.type,
            value: String(value)
        }
    ],
    accesspoint: flow.get("$parent.stm32_accesspoint") || 0
};

return msg;

// @ts-nocheck
const config =
    (msg.payload && msg.payload.variablelist)
        ? msg.payload
        : msg;

const vars = config.variablelist;

if (!Array.isArray(vars)) {
    return msg;
}

for (let i = 0; i < vars.length; i++) {
    const v = vars[i];

    flow.set("stm32_" + v.name, {
        address: v.address,
        type: v.type
    });
}

flow.set(
    "stm32_accesspoint",
    config.accesspoint !== undefined
        ? config.accesspoint
        : 0
);

return msg;

